ST.xhtml:p:
RTrigger1(CLK := g_bWeldCheckEnableM);
RTrigger2(CLK := g_bWeldCheckDisenableM);
RTrigger_M313(CLK := g_bM313EnableM);
RTrigger_CameraDone(CLK := g_biJiaQiangWeldCheckCameraDone OR bCameraDoneHMIFlag);
RTrigger_CameraResualtDone(CLK := g_biJiaQiangCameraWeldCheckResault OR bCameraResualtDoneHMIFlag OR bCameraResualtDoneTest);


IF RTrigger_CameraDone.Q THEN
  bCameraCheckDoneFlag := TRUE;
  bCameraDoneHMIFlag := FALSE;
END_IF;

IF RTrigger1.Q THEN
  IF g_dM178PassedPValue = 0.0 THEN
    nWeldState := 1;
    g_boWeldCheckDone := FALSE;
    g_boWeldSecond := FALSE;
    g_boFindEage := FALSE;
    dCurrentUCoordinate := g_fiUCncCoord;
  END_IF;
  dWeldCheckMode := M.PARAMETER_P[178];
  IF dWeldCheckMode = 2.0 THEN
    g_boJiaQiangCameraWeldCheckSignal := TRUE;
    bCameraCheckDoneFlag := FALSE;

  END_IF;
   g_foWeldPos :=0.0;
  M.ENABLE[178] := 0;
  g_bWeldCheckEnableM := FALSE;
  bWeldCheckDone := FALSE;
END_IF;

IF RTrigger2.Q THEN
  g_bWeldCheckDisenableM:= FALSE;
  g_boJiaQiangCameraWeldCheckSignal := FALSE;
  IF nWeldState = 1 THEN
    nWeldState := 20;
    g_bNoFindWeld := TRUE;
  ELSE
    g_bNoFindWeld := FALSE;
  END_IF;
  g_dM178PassedPValue := 0.0;
  IF M.PARAMETER_P[179] = 0.0 THEN
    bWeldCheckDone := TRUE;
  ELSIF M.PARAMETER_P[179] = 1.0 THEN
    g_bNoFindWeld := TRUE;
  ELSIF M.PARAMETER_P[179] = 2.0 THEN
    dWeldCheckSuccessCount := dWeldCheckSuccessCount +1.0;
  ELSIF M.PARAMETER_P[179] = 3.0 THEN
    dWeldCheckSuccessCount := 0.0;
	dWeldCheckCount := 0.0;
  ELSIF M.PARAMETER_P[179] = 4.0 THEN
    dWeldCheckCount := dWeldCheckCount + 1.0;
  END_IF;
END_IF;


IF RTrigger_M313.Q THEN
  TonDelay_WaitCheckDelay(IN := FALSE);
  g_bM313EnableM := FALSE;
  IF dWeldCheckMode <> 2.0 THEN
	  g_foWeldPos :=999.0;
	  nWeldState := 50;
  ELSIF dWeldCheckMode = 2.0 THEN
    nWeldState := 100;(*去检测拍照完成信号和拍照结果*)
  END_IF;

END_IF;

CASE nWeldState OF 
  0:
    nWeldState := 0;
  1:
    IF g_bWeldCheck THEN(*实际硬件信号*)
      dWeldPos := g_fiUCncCoord;
      nWeldState := 2;
      g_boFindEage := TRUE;
    END_IF;
    IF g_fiUCncCoord - dCurrentUCoordinate >= (WeldLaps * 360.0 -0.5) THEN
      g_boFindEage := TRUE;
    END_IF;
  2:
    g_foWeldPos := dWeldPos;
    g_boWeldCheckDone := TRUE;
    g_boWeldSecond := TRUE;
    M.ENABLE[178] := 0;
  20:
    TonDelay(IN := TRUE,PT := T#1000ms);
    IF TonDelay.Q THEN
      nWeldState := 21;
    END_IF;
  21:
    IF g_bPlcStartBuffer THEN
      g_boWeldSecond := TRUE;
      nWeldState := 0;
      g_bNoFindWeld := FALSE;
    END_IF;
  50:
    TonDelay_WaitCheckDelay(IN := TRUE,PT := LREAL_TO_TIME(M.PARAMETER_P[313]));
    IF TonDelay_WaitCheckDelay.Q THEN
      TonDelay_WaitCheckDelay(IN := FALSE);
      g_bCameraNotFeedBackSignalAlarm := TRUE;
      nWeldState := 0;
    END_IF;
    IF g_foWeldPos <> 999.0 THEN
      TonDelay_WaitCheckDelay(IN := FALSE);
      M.ENABLE[313] := 0;
      nWeldState := 0;
    END_IF;
  100:
	TonDelay_WaitCheckDelay(IN := TRUE,PT := LREAL_TO_TIME(M.PARAMETER_P[313]));
    IF TonDelay_WaitCheckDelay.Q THEN
      TonDelay_WaitCheckDelay(IN := FALSE);
      nWeldState := 0;
      IF bCameraCheckDoneFlag THEN
		M.ENABLE[313] := 0;
      ELSE
        g_bCameraNotFeedBackSignalAlarm := TRUE;
      END_IF;
    END_IF;

    IF RTrigger_CameraResualtDone.Q THEN
      TonDelay_WaitCheckDelay(IN := FALSE);
      IF NOT bCameraResualtDoneTest THEN
		g_foWeldPos := 1.0;
      END_IF;
      M.ENABLE[313] := 0;
      nWeldState := 0;
      bCameraResualtDoneHMIFlag := FALSE;
      bCameraResualtDoneTest := FALSE;
    END_IF;

END_CASE;

IF g_bPlcResetBuffer THEN
  nWeldState := 0;
  g_bNoFindWeld := FALSE;
  g_boJiaQiangCameraWeldCheckSignal := FALSE;
END_IF;
